package android.provider;import android.net.Uri;public class DocumentsContract {public static class Document{public static final String COLUMN_DOCUMENT_ID="id",COLUMN_DISPLAY_NAME="name";}public static String getTreeDocumentId(Uri u){return u.getPath().split("/")[2];}public static String getDocumentId(Uri u){String p=u.getPath();int i=p.lastIndexOf("/document/");if(i<0)throw new IllegalArgumentException();return p.substring(i+10);}public static Uri buildChildDocumentsUriUsingTree(Uri u,String id){return Uri.parse(u+"/children");}public static Uri buildDocumentUriUsingTree(Uri u,String id){return Uri.parse(u+"/document/"+id);}public static boolean deleteDocument(android.content.ContentResolver r,Uri u){return r.delete(u);}}